export const GANGES_STOPS=[{id:"stop-1",stopNumber:1,name:"Gangotri Glacier & Gaumukh",location:"Uttarkashi District, Uttarakhand",elevation:"4,100 m (13,450 ft)",elevationMeters:4100,distanceKm:0,coordinates:"30.92° N, 78.93° E",tag:"Glacial Origin & Alpine Source",summary:"The river originates as the Bhagirathi at Gaumukh ('Mouth of the Cow'), the terminus of the Gangotri Glacier in the Garhwal Himalayas.",details:"Emerging from the high Garhwal Himalayas at an altitude of 4,100 meters, the Bhagirathi River rushes through steep mountain gorges. At Devprayag, it merges with the Alaknanda River—which originates from the Satopanth Glacier—and from this confluence onward, the river is officially named the Ganges (Ganga).",culturalNote:"Gaumukh and Gangotri are historic pilgrimage destinations, celebrating the alpine birth of India's sacred river.",svgPoint:{x:90,y:50}},{id:"stop-2",stopNumber:2,name:"Haridwar & Rishikesh",location:"Haridwar & Dehradun, Uttarakhand",elevation:"314 m (1,030 ft)",elevationMeters:314,distanceKm:290,coordinates:"29.94° N, 78.16° E",tag:"Descent to Northern Plains",summary:"Flowing past Rishikesh, the Ganges emerges from the Himalayan foothills onto the flat plains at Haridwar.",details:"After descending through the wooded hills of Rishikesh—celebrated for yoga tradition and suspension bridges like Lakshman Jhula—the Ganges enters the vast Indo-Gangetic Plains at Haridwar ('Gateway to the Gods'). Here, the river transitions from a rushing mountain torrent into a wide, serene river, supplying the Upper Ganges Canal constructed in the 1850s.",culturalNote:"Haridwar's Har Ki Pauri ghat is renowned for the evening Ganga Aarti, where floating oil lamps light up the river currents at dusk.",svgPoint:{x:130,y:130}},{id:"stop-3",stopNumber:3,name:"Prayagraj (Triveni Sangam)",location:"Prayagraj District, Uttar Pradesh",elevation:"98 m (321 ft)",elevationMeters:98,distanceKm:780,coordinates:"25.43° N, 81.84° E",tag:"Sacred Confluence & Yamuna Merge",summary:"The historic confluence of the pale green Ganges and deep blue Yamuna rivers.",details:"Prayagraj marks the Triveni Sangam, where the Ganges merges with its largest tributary, the Yamuna River (originating from Yamunotri and flowing past Delhi and Agra). The distinct color boundary between the two rivers is visible at the confluence point. The combined river carries immense volume eastward across the alluvial plains.",culturalNote:"The Sangam is the primary venue for the Kumbh Mela, recognized by UNESCO as Intangible Cultural Heritage, attracting millions of peaceful gathering participants.",svgPoint:{x:250,y:260}},{id:"stop-4",stopNumber:4,name:"Varanasi (Kashi)",location:"Varanasi District, Uttar Pradesh",elevation:"81 m (265 ft)",elevationMeters:81,distanceKm:990,coordinates:"25.31° N, 83.01° E",tag:"Cultural & Spiritual Heartland",summary:"One of the world's oldest continuously inhabited cities, stretching along a majestic crescent bend of the Ganges.",details:"In Varanasi, the Ganges turns northward (Uttaravahini), an orientation considered auspicious in classical Indian geography. Eighty-eight stone ghats line the riverfront, serving as centers for morning prayers, classical Hindustani music, Banarasi silk weaving, and historic literary traditions.",culturalNote:"Ghats such as Dashashwamedh and Manikarnika reflect the town's central role in Indian heritage, philosophy, and literature for millennia.",svgPoint:{x:320,y:290}},{id:"stop-5",stopNumber:5,name:"Patna & Middle Plains",location:"Patna District, Bihar",elevation:"53 m (174 ft)",elevationMeters:53,distanceKm:1480,coordinates:"25.59° N, 85.13° E",tag:"Ancient Imperial Cradle & Agriculture",summary:"Passing ancient Pataliputra, the Ganges expands into a vast watercourse joined by major Himalayan tributaries.",details:"As the river traverses Bihar, it absorbs major tributaries including the Ghaghara, Gandak, and Kosi rivers. The surrounding fertile floodplains form one of the world's most productive agricultural zones, sustaining rice, wheat, and sugarcane farming for thousands of years.",culturalNote:"Patna (historic Pataliputra) served as the imperial capital of the Maurya and Gupta empires, connecting ancient riverine trade networks.",svgPoint:{x:400,y:320}},{id:"stop-6",stopNumber:6,name:"Bengal Delta & Sundarbans",location:"West Bengal & Bay of Bengal",elevation:"0 m (Sea Level)",elevationMeters:0,distanceKm:2525,coordinates:"21.94° N, 89.18° E",tag:"World's Largest River Delta",summary:"Splitting into distributaries like the Hooghly and Padma, the Ganges empties into the Bay of Bengal through the Sundarbans.",details:"Near Farakka, the river branches: the Hooghly flows south past Kolkata, while the Padma flows into Bangladesh to join the Brahmaputra (Jamuna) and Meghna. Together, they form the 350-km-wide Ganges-Brahmaputra Delta, entering the sea through the UNESCO World Heritage Sundarbans mangrove forest, home to the Royal Bengal Tiger.",culturalNote:"Kolkata's Hooghly riverfront features the iconic Howrah Bridge and centuries of maritime trade heritage.",svgPoint:{x:470,y:430}}];export function getActiveStopIndex(e=0,t=[]){if(!t||0===t.length)return 0;const a=e+.4*(window.innerHeight||600);let n=0;for(let e=0;e<t.length;e++){a>=t[e].top&&(n=e)}return n}export function calculateRiverPathProgress(e=0,t=6){const a=Math.max(1,t-1),n=Math.max(0,Math.min(a,e));return Math.round(n/a*100)}export function getGangesStats(e=GANGES_STOPS){const t=e.length;return{totalStops:t,totalLengthKm:t>0?e[t-1].distanceKm:2525,originElevation:t>0?e[0].elevation:"4,100 m",seaElevation:t>0?e[t-1].elevation:"0 m",statesTraversed:["Uttarakhand","Uttar Pradesh","Bihar","Jharkhand","West Bengal"]}}class GangesScrollytellingApp{constructor(){this.activeStopIndex=0,this.stopOffsets=[],this.observer=null,this.initElements(),this.bindEvents(),this.renderStops(),this.initIntersectionObserver(),this.updateActiveStop(0)}initElements(){this.narrativeContainer=document.getElementById("narrative-panels-container"),this.jumpNavContainer=document.getElementById("jump-nav-container"),this.meterDistanceEl=document.getElementById("meter-distance"),this.meterElevationEl=document.getElementById("meter-elevation"),this.meterLocationEl=document.getElementById("meter-location"),this.pathProgressBar=document.getElementById("river-progress-fill"),this.svgPath=document.getElementById("ganges-svg-path"),this.svgNodeMarker=document.getElementById("svg-node-marker")}bindEvents(){window.addEventListener("scroll",()=>this.handleScroll(),{passive:!0}),window.addEventListener("resize",()=>this.recalculateOffsets(),{passive:!0});const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme")})}renderStops(){this.narrativeContainer&&(this.narrativeContainer.innerHTML="",this.jumpNavContainer&&(this.jumpNavContainer.innerHTML=""),GANGES_STOPS.forEach((e,t)=>{const a=document.createElement("article");if(a.className="stop-card",a.id=e.id,a.dataset.stopIndex=t,a.innerHTML=`\n        <div class="card-tag-badge">${e.tag}</div>\n        <div class="card-header">\n          <span class="stop-num-badge">Stop ${e.stopNumber} of ${GANGES_STOPS.length}</span>\n          <span class="stop-dist-pill">📍 ${e.distanceKm} km from origin</span>\n        </div>\n        <h2 class="stop-title">${e.name}</h2>\n        <div class="stop-meta-line">\n          <span>🏞️ ${e.location}</span> • <span>⛰️ ${e.elevation}</span>\n        </div>\n        <p class="stop-summary">${e.summary}</p>\n        <p class="stop-details">${e.details}</p>\n        <div class="cultural-box">\n          <span class="cultural-icon">🏛️</span>\n          <p class="cultural-text"><strong>Heritage & Culture:</strong> ${e.culturalNote}</p>\n        </div>\n      `,this.narrativeContainer.appendChild(a),this.jumpNavContainer){const n=document.createElement("button");n.type="button",n.className="jump-btn "+(0===t?"active":""),n.dataset.stopIndex=t,n.textContent=`${t+1}. ${e.name.split(" ")[0]}`,n.addEventListener("click",()=>{a.scrollIntoView({behavior:"smooth",block:"center"})}),this.jumpNavContainer.appendChild(n)}}),this.recalculateOffsets())}recalculateOffsets(){const e=document.querySelectorAll(".stop-card");this.stopOffsets=Array.from(e).map(e=>{const t=e.getBoundingClientRect(),a=window.scrollY||document.documentElement.scrollTop;return{id:e.id,top:t.top+a,height:t.height}})}initIntersectionObserver(){if("undefined"==typeof IntersectionObserver)return;this.observer=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const t=parseInt(e.target.dataset.stopIndex,10);isNaN(t)||this.updateActiveStop(t)}})},{rootMargin:"-20% 0px -40% 0px",threshold:.2});document.querySelectorAll(".stop-card").forEach(e=>this.observer.observe(e))}handleScroll(){const e=getActiveStopIndex(window.scrollY||document.documentElement.scrollTop,this.stopOffsets);e!==this.activeStopIndex&&this.updateActiveStop(e)}updateActiveStop(e){this.activeStopIndex=e;const t=GANGES_STOPS[e];if(!t)return;if(this.meterDistanceEl&&(this.meterDistanceEl.textContent=`${t.distanceKm} km`),this.meterElevationEl&&(this.meterElevationEl.textContent=t.elevation),this.meterLocationEl&&(this.meterLocationEl.textContent=t.name),this.pathProgressBar){const t=calculateRiverPathProgress(e,GANGES_STOPS.length);this.pathProgressBar.style.width=`${t}%`}if(this.jumpNavContainer){this.jumpNavContainer.querySelectorAll(".jump-btn").forEach((t,a)=>{t.classList.toggle("active",a===e)})}document.querySelectorAll(".stop-card").forEach((t,a)=>{t.classList.toggle("active",a===e)}),this.svgNodeMarker&&t.svgPoint&&(this.svgNodeMarker.setAttribute("cx",t.svgPoint.x),this.svgNodeMarker.setAttribute("cy",t.svgPoint.y))}}"undefined"!=typeof window&&"undefined"!=typeof document&&(window.GangesScrollytelling={GANGES_STOPS:GANGES_STOPS,getActiveStopIndex:getActiveStopIndex,calculateRiverPathProgress:calculateRiverPathProgress,getGangesStats:getGangesStats,GangesScrollytellingApp:GangesScrollytellingApp},document.addEventListener("DOMContentLoaded",()=>{document.getElementById("narrative-panels-container")&&new GangesScrollytellingApp}));